INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Spring-w1-Ballers','Spring',1,'Ballers',NULL,'{"id":"Spring-w1-Ballers","term":"Spring","week":1,"ageGroup":"Ballers","ageRange":"12-15 Years","length":"45 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Leadership","time":"4m","huddle":{"coreValue":"Leadership","quote":"Leadership isn''t about being in charge; it''s about taking care of those in your charge and inspiring them through your actions."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"23m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Summer-w1-Ballers','Summer',1,'Ballers',NULL,'{"id":"Summer-w1-Ballers","term":"Summer","week":1,"ageGroup":"Ballers","ageRange":"12-15 Years","length":"45 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Love","time":"4m","huddle":{"coreValue":"Love","quote":"This is the last week of term. Make it count. Make it joyful, celebratory, and reflective in equal measure. Give every child a specific moment of personal recognition — something they did this term that you saw, that mattered, that you will remember. Ask them: what do you love about this? Their answers will tell you everything about how well you have done your job. And then ask yourself the same question — because if you still love it, they will feel it. And if they feel it, they will come back."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"23m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Summer-w4-RisingStars','Summer',4,'Rising Stars',NULL,'{"id":"Summer-w4-RisingStars","term":"Summer","week":4,"ageGroup":"Rising Stars","ageRange":"8-11 Years","length":"45 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Fair Play","time":"4m","huddle":{"coreValue":"Fair Play","quote":"Fair play is about integrity. It''s competing with everything you have while maintaining total honesty and sportsmanship."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a5","segment":"Skills 2","name":"Freeze Tag","time":"5m","drill":{"summary":"Players dribble within a boundary while designated Taggers try to ''freeze'' them by tagging them. If tagged stand with legs apart and ball in the air. If a team mate dribbles their ball through your legs you are unfrozen and rejoin the game!","focus":"Dribbling","video":"https://youtu.be/89PdzbwKCVg?si=vgAYaqlB-0ao4sca","easy":"Reduce the playing area to to encourage more frequent stops and starts.","expert":"The Tagger must also dribble a ball while trying to freeze the other players.","coachCues":"Stay low like a Hero! Use your low dribble superpower to change directions."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"18m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Spring-w9-RisingStars','Spring',9,'Rising Stars',NULL,'{"id":"Spring-w9-RisingStars","term":"Spring","week":9,"ageGroup":"Rising Stars","ageRange":"8-11 Years","length":"45 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Inclusion","time":"4m","huddle":{"coreValue":"Inclusion","quote":"Deliver and adapt sessions so that every child can succeed — not just the most able. Watch for children who are drifting quietly and bring them back in. Never let a child be made to feel lesser by their peers without addressing it directly. Actively celebrate different styles of play, different starting points, different personalities. Make sure every child leaves having contributed something that was seen and valued."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a5","segment":"Skills 2","name":"Freeze Tag","time":"5m","drill":{"summary":"Players dribble within a boundary while designated Taggers try to ''freeze'' them by tagging them. If tagged stand with legs apart and ball in the air. If a team mate dribbles their ball through your legs you are unfrozen and rejoin the game!","focus":"Dribbling","video":"https://youtu.be/89PdzbwKCVg?si=vgAYaqlB-0ao4sca","easy":"Reduce the playing area to to encourage more frequent stops and starts.","expert":"The Tagger must also dribble a ball while trying to freeze the other players.","coachCues":"Stay low like a Hero! Use your low dribble superpower to change directions."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"18m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
