INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Spring-w10-Rookies','Spring',10,'Rookies',NULL,'{"id":"Spring-w10-Rookies","term":"Spring","week":10,"ageGroup":"Rookies","ageRange":"5-7 Years","length":"30 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Growth","time":"4m","huddle":{"coreValue":"Growth","quote":"Give feedback that references growth specifically: ''That is so much better than last week — I have watched you work on that.'' Never compare children to each other — always compare them to themselves. Teach children to self-coach: ''What are you working on today? How will you know if it worked?'' Set the expectation that every session contains progress. The child who leaves knowing exactly what they improved is developing the Hero''s Mindset."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a5","segment":"Skills 2","name":"Freeze Tag","time":"5m","drill":{"summary":"Players dribble within a boundary while designated Taggers try to ''freeze'' them by tagging them. If tagged stand with legs apart and ball in the air. If a team mate dribbles their ball through your legs you are unfrozen and rejoin the game!","focus":"Dribbling","video":"https://youtu.be/89PdzbwKCVg?si=vgAYaqlB-0ao4sca","easy":"Reduce the playing area to to encourage more frequent stops and starts.","expert":"The Tagger must also dribble a ball while trying to freeze the other players.","coachCues":"Stay low like a Hero! Use your low dribble superpower to change directions."}},{"id":"a6","segment":"Skills 3","name":"Numbers Game","time":"5m","drill":{"summary":"Assign each player a number. When their number is called, they run out, receive a pass, and play 1v1 to the basket.","focus":"Dribbling, Shooting, Defence","easy":"Call numbers one at a time.","expert":"Call multiple numbers for 2v2 or 3v3.","coachCues":"Listen closely! Attack the basket quickly!"}},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
