INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Autumn-w10-RisingStars','Autumn',10,'Rising Stars',NULL,'{"id":"Autumn-w10-RisingStars","term":"Autumn","week":10,"ageGroup":"Rising Stars","ageRange":"8-11 Years","length":"45 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Inclusion","time":"4m","huddle":{"coreValue":"Inclusion","quote":"Deliver and adapt sessions so that every child can succeed — not just the most able. Watch for children who are drifting quietly and bring them back in. Never let a child be made to feel lesser by their peers without addressing it directly. Actively celebrate different styles of play, different starting points, different personalities. Make sure every child leaves having contributed something that was seen and valued."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a5","segment":"Skills 2","name":"Freeze Tag","time":"5m","drill":{"summary":"Players dribble within a boundary while designated Taggers try to ''freeze'' them by tagging them. If tagged stand with legs apart and ball in the air. If a team mate dribbles their ball through your legs you are unfrozen and rejoin the game!","focus":"Dribbling","video":"https://youtu.be/89PdzbwKCVg?si=vgAYaqlB-0ao4sca","easy":"Reduce the playing area to to encourage more frequent stops and starts.","expert":"The Tagger must also dribble a ball while trying to freeze the other players.","coachCues":"Stay low like a Hero! Use your low dribble superpower to change directions."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"18m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Summer-w12-Ballers','Summer',12,'Ballers',NULL,'{"id":"Summer-w12-Ballers","term":"Summer","week":12,"ageGroup":"Ballers","ageRange":"12-15 Years","length":"45 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Growth","time":"4m","huddle":{"coreValue":"Growth","quote":"Give feedback that references growth specifically: ''That is so much better than last week — I have watched you work on that.'' Never compare children to each other — always compare them to themselves. Teach children to self-coach: ''What are you working on today? How will you know if it worked?'' Set the expectation that every session contains progress. The child who leaves knowing exactly what they improved is developing the Hero''s Mindset."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"23m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Summer-w9-RisingStars','Summer',9,'Rising Stars',NULL,'{"id":"Summer-w9-RisingStars","term":"Summer","week":9,"ageGroup":"Rising Stars","ageRange":"8-11 Years","length":"45 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Perseverance","time":"4m","huddle":{"coreValue":"Perseverance","quote":"Perseverance is failing 19 times and succeeding the 20th. It''s the grit to keep going when things get tough."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a5","segment":"Skills 2","name":"Freeze Tag","time":"5m","drill":{"summary":"Players dribble within a boundary while designated Taggers try to ''freeze'' them by tagging them. If tagged stand with legs apart and ball in the air. If a team mate dribbles their ball through your legs you are unfrozen and rejoin the game!","focus":"Dribbling","video":"https://youtu.be/89PdzbwKCVg?si=vgAYaqlB-0ao4sca","easy":"Reduce the playing area to to encourage more frequent stops and starts.","expert":"The Tagger must also dribble a ball while trying to freeze the other players.","coachCues":"Stay low like a Hero! Use your low dribble superpower to change directions."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"18m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Spring-w1-RisingStars','Spring',1,'Rising Stars',NULL,'{"id":"Spring-w1-RisingStars","term":"Spring","week":1,"ageGroup":"Rising Stars","ageRange":"8-11 Years","length":"45 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Leadership","time":"4m","huddle":{"coreValue":"Leadership","quote":"Leadership isn''t about being in charge; it''s about taking care of those in your charge and inspiring them through your actions."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a5","segment":"Skills 2","name":"Freeze Tag","time":"5m","drill":{"summary":"Players dribble within a boundary while designated Taggers try to ''freeze'' them by tagging them. If tagged stand with legs apart and ball in the air. If a team mate dribbles their ball through your legs you are unfrozen and rejoin the game!","focus":"Dribbling","video":"https://youtu.be/89PdzbwKCVg?si=vgAYaqlB-0ao4sca","easy":"Reduce the playing area to to encourage more frequent stops and starts.","expert":"The Tagger must also dribble a ball while trying to freeze the other players.","coachCues":"Stay low like a Hero! Use your low dribble superpower to change directions."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"18m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
INSERT OR REPLACE INTO session_plans (id,term,week,age_group,location_id,data) VALUES ('Autumn-w12-Rookies','Autumn',12,'Rookies',NULL,'{"id":"Autumn-w12-Rookies","term":"Autumn","week":12,"ageGroup":"Rookies","ageRange":"5-7 Years","length":"30 Min","activities":[{"id":"a1","segment":"Huddle, Registration","name":"CORE VALUE: Accountability","time":"4m","huddle":{"coreValue":"Accountability","quote":"Own your own mistakes as a coach — visibly, without excuse, in front of the children. This is the single most powerful accountability lesson you will ever teach them. Hold children to their commitments consistently and kindly: ''You said you were going to box out every time — I am watching for it.'' Do not accept deflection without gently redirecting it: ''I hear you — and what could you have done differently?'' The team that holds itself to account, without the coach having to enforce every standard, is a team ready to achieve something."}},{"id":"a2","segment":"Warm Up","name":"Bulldozers and Builders / Construction Site","time":"5m","drill":{"summary":"Half the group (Builders) stands cones up, the other half (Bulldozers) tips them over. Players must dribble while doing their task. After 60 seconds, switch roles. Most cones in their position wins.","focus":"Dribbling","video":"https://youtu.be/8rS7nP_Npgg","easy":"Builders and Bulldozers don''t dribble, they just move between cones to focus on the game mechanics.","expert":"Add a 30-second time limit for the Bulldozers to tip all the cones over before the Builders can stop them.","coachCues":"Keep your Hero Vision up! Keep your ball close while you help your team build or bulldoze."}},{"id":"a3","segment":"TIMEOUT","name":"Hydrate and split into groups by age & ability","time":"2m"},{"id":"a4","segment":"Skills 1","name":"Team Tally Passing","time":"5m","drill":{"summary":"Two teams of 3 compete to make 5 consecutive passes without an interception then place the ball on the floor to score. No dribbling allowed.","focus":"Passing","video":"https://youtu.be/8rS7nP_Npgg","easy":"Decrease the number of consecutive passes required to 3.","expert":"Require all passes to be bounce passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a5","segment":"Skills 2","name":"Freeze Tag","time":"5m","drill":{"summary":"Players dribble within a boundary while designated Taggers try to ''freeze'' them by tagging them. If tagged stand with legs apart and ball in the air. If a team mate dribbles their ball through your legs you are unfrozen and rejoin the game!","focus":"Dribbling","video":"https://youtu.be/89PdzbwKCVg?si=vgAYaqlB-0ao4sca","easy":"Reduce the playing area to to encourage more frequent stops and starts.","expert":"The Tagger must also dribble a ball while trying to freeze the other players.","coachCues":"Stay low like a Hero! Use your low dribble superpower to change directions."}},{"id":"a6","segment":"Skills 3","name":"Numbers Game","time":"5m","drill":{"summary":"Assign each player a number. When their number is called, they run out, receive a pass, and play 1v1 to the basket.","focus":"Dribbling, Shooting, Defence","easy":"Call numbers one at a time.","expert":"Call multiple numbers for 2v2 or 3v3.","coachCues":"Listen closely! Attack the basket quickly!"}},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
