e passes.","coachCues":"Call your teammate''s name before passing! Step into your pass."}},{"id":"a7","segment":"TIMEOUT","name":"Hydrate and Split into teams for Small Sided Games","time":"2m"},{"id":"a8","segment":"Small Sided Games","name":"Small Sided Games 3v3","time":"23m"},{"id":"a99","segment":"Wrap up","name":"REFLECTION & REWARDS","time":"4m"}]}');
